('cleric-divine-spark-damage', (SELECT id FROM rpg.phb_class WHERE slug = 'cleric'), NULL, 'Centelha Divina — Dano', 'bonus'::rpg.action_economy_bucket, 2, 'channelDivinity', NULL, true, 'Canalizar: Necrótico/Radiante (CON)', 'Gaste 1 Canalizar Divindade. Alvo a 9 m: Constituição vs CD → dano Necrótico ou Radiante (dados + Sabedoria), metade no sucesso.', 'divine-spark-damage', NULL, 47),
