('sorcerer-bastion-of-law', (SELECT id FROM rpg.phb_class WHERE slug = 'sorcerer'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'clockwork'), 'Bastião da Lei', 'action'::rpg.action_economy_bucket, 6, 'sorceryPoints', NULL, true, 'Gaste 1–5 SP: conceda N d8 de proteção a aliado (9 m)', 'Como ação Usar Magia, gaste de 1 a 5 Pontos de Feitiçaria para criar proteção (N d8). A criatura protegida pode gastar os dados para reduzir dano. Dura até Descanso Longo ou novo uso.', 'bastion-of-law', NULL, 79),
('sorcerer-bend-luck', (SELECT id FROM rpg.phb_class WHERE slug = 'sorcerer'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'wild-magic'), 'Distorcer a Sorte', 'reaction'::rpg.action_economy_bucket, 6, 'sorceryPoints', NULL, true, 'Reação: 1 SP → ±1d4 no d20 de outra criatura', 'Imediatamente após outra criatura à sua vista jogar o d20 para um Teste de D20, use Reação e gaste 1 Ponto de Feitiçaria para aplicar +1d4 ou −1d4 (à sua escolha).', 'bend-luck', 1, 80),
