('warlock-healing-light', (SELECT id FROM rpg.phb_class WHERE slug = 'warlock'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'celestial'), 'Luz Medicinal', 'bonus'::rpg.action_economy_bucket, 3, 'healing-light', NULL, false, 'Cura com reserva de d6s (1–CAR)', 'Como Ação Bônus, gaste 1 até o seu modificador de Carisma em d6s da reserva de Luz Medicinal para curar uma criatura a até 18 m.', 'healing-light', NULL, 64),
('warlock-dark-ones-luck', (SELECT id FROM rpg.phb_class WHERE slug = 'warlock'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'fiend'), 'A Sorte do Próprio Tenebroso', 'free'::rpg.action_economy_bucket, 6, 'dark-ones-luck', NULL, false, '+1d10 em teste ou salvaguarda', 'Quando você fizer um teste de habilidade ou salvaguarda, gaste 1 uso para rolar 1d10 e somar ao resultado. O Usar rola o d10 e gasta o uso; marque o bônus na mesa.', 'dark-ones-luck', NULL, 65),
('warlock-fey-steps', (SELECT id FROM rpg.phb_class WHERE slug = 'warlock'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'archfey'), 'Passos Feéricos', 'bonus'::rpg.action_economy_bucket, 3, 'fey-steps', NULL, true, 'Passo Nebuloso sem espaço + efeito', 'Gaste 1 uso para conjurar Passo Nebuloso sem espaço. Escolha o efeito na mesa: Provocante ou Revigorante (nv. 6+: também Desvanecedor ou Terrível).', 'fey-step-effect', NULL, 72),
('warlock-beguiling-defenses', (SELECT id FROM rpg.phb_class WHERE slug = 'warlock'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'archfey'), 'Defesas Sedutoras', 'reaction'::rpg.action_economy_bucket, 10, 'beguiling-defenses', NULL, true, 'Reação após ser acertado: metade do dano + psíquico', NULL, 'beguiling-defenses', NULL, 73),
