('warlock-awakened-mind', (SELECT id FROM rpg.phb_class WHERE slug = 'warlock'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'great-old-one'), 'Mente Desperta', 'bonus'::rpg.action_economy_bucket, 3, NULL, NULL, false, 'Telepatia a 9 m; magias psíquicas', 'Como Ação Bônus, estabeleça ligação telepática com uma criatura a até 9 m. Magias Psíquicas: dano de Bruxo pode ser Psíquico; Encantamento/Ilusão sem componentes V/S (mesa).', 'awakened-mind', NULL, 74),
('warlock-searing-vengeance', (SELECT id FROM rpg.phb_class WHERE slug = 'warlock'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'celestial'), 'Vingança Calcinante', 'reaction'::rpg.action_economy_bucket, 14, 'searing-vengeance', NULL, true, 'Salvaguarda contra morte (você/aliado 18 m)', NULL, 'searing-vengeance', NULL, 75),
('warlock-hurl-through-hell', (SELECT id FROM rpg.phb_class WHERE slug = 'warlock'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'fiend'), 'Lançar no Inferno', 'free'::rpg.action_economy_bucket, 14, 'hurl-through-hell', NULL, true, 'Ao acertar: envie o alvo aos Infernos (1×/DL)', NULL, 'hurl-through-hell', NULL, 76),
('wizard-improved-illusions', (SELECT id FROM rpg.phb_class WHERE slug = 'wizard'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'illusionist'), 'Ilusão Aprimorada', 'bonus'::rpg.action_economy_bucket, 3, NULL, NULL, false, 'Conjurar ilusões como Ação Bônus (sem componente V)', 'Conjure truques de Ilusão e Imagem Silenciosa como Ação Bônus sem componentes V e com o dobro do alcance.', 'improved-illusions', NULL, 66),
('wizard-arcane-ward', (SELECT id FROM rpg.phb_class WHERE slug = 'wizard'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'abjurer'), 'Proteção Arcana', 'free'::rpg.action_economy_bucket, 3, NULL, NULL, false, 'Ativar barreira mágica (PV temp)', 'Ative a Proteção Arcana: barreira com PV iguais ao dobro do seu nível de Mago + modificador de Inteligência. Absorve dano sofrido e recarrega ao conjurar magias de Abjuração. O Usar calcula e anota os PV na mesa.', 'arcane-ward', NULL, 71),
('wizard-arcane-ward-recharge', (SELECT id FROM rpg.phb_class WHERE slug = 'wizard'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'abjurer'), 'Recarregar Proteção Arcana', 'bonus'::rpg.action_economy_bucket, 3, NULL, NULL, false, 'Ação Bônus: gastar slot → Proteção recupera 2× círculo', 'Como Ação Bônus, gaste um espaço de magia: a Proteção Arcana recupera Pontos de Vida iguais ao dobro do círculo do espaço gasto.', 'arcane-ward-recharge', NULL, 72),
('wizard-projected-ward', (SELECT id FROM rpg.phb_class WHERE slug = 'wizard'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'abjurer'), 'Proteção Projetada', 'reaction'::rpg.action_economy_bucket, 6, NULL, NULL, false, 'Reação: sua Proteção absorve dano de aliado a até 9 m', 'Quando uma criatura à sua vista a até 9 m sofrer dano, use sua Reação para que a Proteção Arcana absorva esse dano no lugar dela (conforme o texto da característica).', 'projected-ward', NULL, 73),
('wizard-spell-breaker', (SELECT id FROM rpg.phb_class WHERE slug = 'wizard'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'abjurer'), 'Rompe-Magia (Dissipar)', 'bonus'::rpg.action_economy_bucket, 10, NULL, NULL, false, 'Dissipar Magia como Ação Bônus (+PB no teste)', 'Você sempre tem Contramagia e Dissipar Magia preparadas. Pode conjurar Dissipar Magia como Ação Bônus e soma o Bônus de Proficiência ao teste. Se Dissipar ou Contramagia falharem ao interromper uma magia, o espaço não é gasto.', 'spell-breaker', NULL, 74),
('wizard-third-eye', (SELECT id FROM rpg.phb_class WHERE slug = 'wizard'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'diviner'), 'O Terceiro Olho', 'bonus'::rpg.action_economy_bucket, 10, 'third-eye', NULL, true, 'Ação Bônus: Compreensão / Ver o Invisível / Visão no Escuro', 'Como Ação Bônus, escolha um benefício até o próximo descanso: Compreensão Superior (ler qualquer idioma), Ver o Invisível (sem espaço) ou Visão no Escuro 36 m. 1× por Descanso Curto ou Longo.', 'third-eye', NULL, 75),
('wizard-portent', (SELECT id FROM rpg.phb_class WHERE slug = 'wizard'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'diviner'), 'Rolar Presságio', 'free'::rpg.action_economy_bucket, 3, NULL, NULL, false, 'Rolar dados de Presságio do dia', 'Após um Descanso Longo, role os dados de Presságio (2d20; 3d20 no nv. 14+) e guarde os resultados. Substitua qualquer d20 seu ou de uma criatura por um desses números (mesa). O Usar rola e anota os valores do dia.', 'portent', NULL, 75),
('wizard-spectral-summon', (SELECT id FROM rpg.phb_class WHERE slug = 'wizard'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'illusionist'), 'Criaturas Espectrais', 'action'::rpg.action_economy_bucket, 6, 'spectral-summon', NULL, true, 'Convocar Feérico / Invocar Fera (ilusão, PV metade) sem slot', 'Conjure a versão Ilusão de Convocar Feérico ou Invocar Fera sem espaço (PV da criatura pela metade). Após usar qualquer uma sem slot, recupere o uso só no Descanso Longo.', 'spectral-summon', NULL, 76),
('wizard-illusory-self', (SELECT id FROM rpg.phb_class WHERE slug = 'wizard'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'illusionist'), 'Autoimagem Ilusória', 'reaction'::rpg.action_economy_bucket, 10, 'illusory-self', NULL, true, 'Reação ao ser atingido: ataque erra; 1×/Descanso', 'Ao ser atingido por um ataque, use a Reação: duplicata ilusória faz o ataque errar automaticamente. Restaure o uso no Descanso Curto/Longo ou gastando um espaço de 2º+ (sem ação).', 'illusory-self', NULL, 77),
('wizard-illusory-reality', (SELECT id FROM rpg.phb_class WHERE slug = 'wizard'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'illusionist'), 'Realidade Ilusória', 'bonus'::rpg.action_economy_bucket, 14, NULL, NULL, false, 'Ação Bônus: tornar real 1 objeto da ilusão (1 min)', 'Enquanto uma magia de Ilusão conjurada com espaço estiver ativa, como Ação Bônus torne real um objeto inanimado não mágico da ilusão por 1 minuto (não causa dano nem condições).', 'illusory-reality', NULL, 78),
('wizard-overchannel', (SELECT id FROM rpg.phb_class WHERE slug = 'wizard'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'evoker'), 'Sobrecarga', 'free'::rpg.action_economy_bucket, 14, NULL, NULL, false, 'Ao conjurar (1º–5º): dano máximo; usos extras → Necrótico', 'Ao conjurar magia de Mago que causa dano com espaço de 1º a 5º, você pode causar dano máximo nesse turno. A 1ª vez no dia não tem custo; usos seguintes antes do Descanso Longo causam 2d12 Necrótico por círculo (+1d12 a cada uso extra), ignorando Resistência/Imunidade.', 'overchannel', NULL, 79),
('wizard-sculpt-spells', (SELECT id FROM rpg.phb_class WHERE slug = 'wizard'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'evoker'), 'Esculpir Magias', 'free'::rpg.action_economy_bucket, 6, NULL, NULL, false, 'Proteger aliados na área de Evocação', 'Ao conjurar magia de Evocação que afeta outras criaturas que você possa ver, escolha até 1 + nível da magia aliados na área. Eles passam automaticamente na salvaguarda e não sofrem dano. Use para marcar a escolha na mesa.', 'sculpt-spells', NULL, 80),
('wizard-mm-free', (SELECT id FROM rpg.phb_class WHERE slug = 'wizard'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'magic-missile-mage'), 'Mísseis Mágicos Gratuitos', 'action'::rpg.action_economy_bucket, 3, 'magic-missile-free', NULL, true, 'Conjura Mísseis sem espaço (gasta 1 uso)', $mm_free$Na ficha, Conjurar gasta 1 uso gratuito e conjura Mísseis Mágicos sem espaço. Dardos extras e penetração entram na nota de mesa.

Sábio dos Mísseis Mágicos. Adicione a magia Mísseis Mágicos ao seu grimório gratuitamente. Sua expertise nesta magia concede os seguintes benefícios.

Dardos Extra. Quando você conjura Mísseis Mágicos, cria um dardo extra de força mágica. Você cria dois dardos extras no nível 6 de Mago, três dardos extras no nível 10 de Mago e quatro dardos extras no nível 14 de Mago.

Conjuração Livre. Você pode conjurar Mísseis Mágicos sem um espaço de magia. Você pode fazer isso um número de vezes igual ao seu modificador de Inteligência (mínimo de uma vez). Você recupera um uso gasto ao terminar um Descanso Curto e recupera todos os usos gastos ao terminar um Descanso Longo.

Dardos Penetrantes. Seus dardos de Mísseis Mágicos ignoram qualquer efeito, como a magia Escudo, que bloqueie especificamente a magia Mísseis Mágicos.$mm_free$, 'cast:misseis-magicos-free', NULL, 67),
('wizard-mm-versatile', (SELECT id FROM rpg.phb_class WHERE slug = 'wizard'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'magic-missile-mage'), 'Mísseis Versáteis', 'free'::rpg.action_economy_bucket, 6, NULL, NULL, false, 'Ao conjurar: Tombo 1 / Cegar 3 / Atordoar 5 dardos', $mm_vers$Você pode guiar com precisão seus dardos de Mísseis Mágicos para atingir um alvo onde escolher. Quando você conjura Mísseis Mágicos, pode adicionar um dos seguintes efeitos de Míssil Versátil a um alvo atingido pelos dardos. Cada efeito tem um custo, que é o número de dardos que você deve abrir mão para adicionar o efeito ao alvo. Você pode adicionar efeitos diferentes a alvos diferentes, pagando o custo de cada efeito separadamente.

Míssil de Tombo (Custo: 1 Dardo). O alvo deve ser bem-sucedido em uma salvaguarda de Força contra sua CD de magia ou ter a condição Caído.

Míssil Cegante (Custo: 3 Dardos). O alvo deve ser bem-sucedido em uma salvaguarda de Constituição contra sua CD de magia ou ter a condição Cego até o início do seu próximo turno.

Míssil Atordoante (Custo: 5 Dardos). O alvo deve ser bem-sucedido em uma salvaguarda de Constituição contra sua CD de magia ou ter a condição Atordoado até o início do seu próximo turno.$mm_vers$, NULL, NULL, 68),
('wizard-missile-shield', (SELECT id FROM rpg.phb_class WHERE slug = 'wizard'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'magic-missile-mage'), 'Escudo de Mísseis', 'free'::rpg.action_economy_bucket, 10, 'missile-shield', NULL, true, 'Armar para o próximo cast (gasta o uso no cast)', $mm_shield$Arme na ficha antes de conjurar Mísseis Mágicos. O uso é gasto no cast (ou restaure com espaço de 3º+).

Quando você conjura Mísseis Mágicos, pode direcionar os dardos em uma órbita apertada ao seu redor, criando uma Emanação protetora de 3 m originada de você, que dura até 1 minuto.

Você ganha um bônus na sua Classe de Armadura igual ao número de dardos orbitando você (bônus máximo de +5). Sempre que uma criatura a até 36 m errar você com uma jogada de ataque, um dardo atinge o atacante, causando dano normalmente e diminuindo em um o número de dardos orbitando você.

Sempre que a Emanação entrar no espaço de uma criatura que você possa ver e sempre que uma criatura que você possa ver entrar na Emanação ou terminar seu turno nela, você pode atingir o alvo com qualquer número de dardos orbitando você, causando dano normalmente e diminuindo o número de dardos orbitando você. Você só pode causar dano a uma criatura com a Emanação uma vez por turno.

Depois de usar este recurso, você não pode usá-lo novamente até terminar um Descanso Longo. Você também pode restaurar seu uso gastando um espaço de magia de nível 3+ (nenhuma ação necessária).$mm_shield$, 'arm:missile-shield', NULL, 69),
('wizard-giga-missile', (SELECT id FROM rpg.phb_class WHERE slug = 'wizard'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'magic-missile-mage'), 'Giga-Míssil', 'free'::rpg.action_economy_bucket, 14, 'giga-missile', NULL, true, 'Armar para o próximo cast (+mod. INT por dardo)', $mm_giga$Arme na ficha antes de conjurar Mísseis Mágicos. O uso é gasto no cast (ou restaure com espaço de 6º+).

Quando você conjura Mísseis Mágicos, pode aprimorar o dano da magia. Você causa dano de Força extra com cada dardo igual ao seu modificador de Inteligência (mínimo de 1).

Depois de usar este recurso, você não pode usá-lo novamente até terminar um Descanso Longo. Você também pode restaurar seu uso gastando um espaço de magia de nível 6+ (nenhuma ação necessária).$mm_giga$, 'arm:giga-missile', NULL, 70),
