('gunslinger-bullet-time', (SELECT id FROM rpg.phb_class WHERE slug = 'gunslinger'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'pistolero'), 'Tempo Bala', 'free'::rpg.action_economy_bucket, 14, NULL, NULL, false, '1×/turno: Vantagem em um ataque à distância', 'Uma vez em cada um dos seus turnos, ao fazer um ataque à distância com arma, você pode ter Vantagem na jogada de ataque (mesa — sem gasto de recurso).', NULL, NULL, 72),
('gunslinger-head-shot', (SELECT id FROM rpg.phb_class WHERE slug = 'gunslinger'), NULL, 'Tiro na Cabeça', 'free'::rpg.action_economy_bucket, 20, NULL, NULL, false, 'Crítico à distância: morte ou +10d10', 'Quando marca um Acerto Crítico com arma de longo alcance, pode declarar Tiro na Cabeça: se o alvo tiver menos de 100 PV, morre; senão, +10d10 do tipo da arma. 1×/Descanso Curto ou Longo, ou restaure gastando 3 Dados de Risco (toggle no card de ataque gasta 3× risk).', NULL, NULL, 73),
('gunslinger-focused-shot', (SELECT id FROM rpg.phb_class WHERE slug = 'gunslinger'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'deadeye'), 'Tiro Focado', 'action'::rpg.action_economy_bucket, 14, NULL, NULL, false, 'Atacar → 1 ataque com Vantagem = crítico', 'Ao usar a ação Atacar, pode fazer apenas um ataque à distância com arma como Tiro Focado: Vantagem na jogada; se acertar, é Acerto Crítico (mesa — sem gasto de recurso).', NULL, NULL, 74),
('gunslinger-risky-business', (SELECT id FROM rpg.phb_class WHERE slug = 'gunslinger'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'high-roller'), 'Negócio Arriscado', 'free'::rpg.action_economy_bucket, 6, NULL, NULL, false, '1×/turno: Desvantagem no ataque → +1 risk', 'Uma vez por turno, ao atacar um inimigo sem Desvantagem, pode declarar Desvantagem na jogada e recuperar 1 Dado de Risco gasto (marque ± na Economia).', NULL, NULL, 75),
('gunslinger-double-or-nothing', (SELECT id FROM rpg.phb_class WHERE slug = 'gunslinger'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'high-roller'), 'Duplo ou Nada', 'free'::rpg.action_economy_bucket, 14, NULL, NULL, false, 'No crítico: d20 — 10+ = ×4 dano; 9− = acerto normal', 'Ao marcar Acerto Crítico com arma de longo alcance, pode apostar: role d20. 10+: role o dano quatro vezes (em vez de duas). 9 ou menos: o crítico vira acerto normal (mesa).', NULL, NULL, 76),
('gunslinger-exit-strategy', (SELECT id FROM rpg.phb_class WHERE slug = 'gunslinger'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'secret-agent'), 'Estratégia de Saída', 'reaction'::rpg.action_economy_bucket, 10, NULL, NULL, false, '1×/descanso: Invisível + 3 m; restaure com 1 risk', 'Reação ao sofrer dano: fica Invisível até o início do seu próximo turno e pode se mover até 3 m. 1×/Descanso Curto ou Longo; restaure gastando 1 Dado de Risco (sem ação — marque na mesa).', NULL, NULL, 77),
('gunslinger-license-to-kill', (SELECT id FROM rpg.phb_class WHERE slug = 'gunslinger'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'secret-agent'), 'Licença para Matar', 'free'::rpg.action_economy_bucket, 14, NULL, NULL, false, '1–2 risk no dano (teto = PB); explode no máximo', 'Ao causar dano com arma de longo alcance, gaste 1 ou 2 Dados de Risco e some-os ao dano. No máximo do dado, rerrole e some sem gastar (continua). Máximo de dados = seu PB (mesa — gaste ± risk).', NULL, NULL, 78),
('gunslinger-arcane-shot', (SELECT id FROM rpg.phb_class WHERE slug = 'gunslinger'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'spellslinger'), 'Tiro Arcano', 'bonus'::rpg.action_economy_bucket, 3, NULL, NULL, false, 'BA: +1 risk no dano de Pistolas de Dedo', 'Ao atingir com Pistolas de Dedo, Ação Bônus: gaste 1 Dado de Risco e some-o à jogada de dano (marque − risk na Economia).', NULL, NULL, 79),
('gunslinger-pinball', (SELECT id FROM rpg.phb_class WHERE slug = 'gunslinger'), (SELECT id FROM rpg.phb_subclass WHERE slug = 'trick-shot'), 'Tiro de Pinball', 'free'::rpg.action_economy_bucket, 14, NULL, NULL, false, '1×/descanso: ricochetes até 5; restaure com 2 risk', '1×/turno ao acertar ataque à distância com arma: desvie o projétil para alvos a até 9 m (até 5 ataques no total; sem repetir alvo). 1×/Descanso Curto ou Longo; restaure gastando 2 Dados de Risco (sem ação).', NULL, NULL, 80)
ON CONFLICT (action_id) DO UPDATE SET
  class_id = EXCLUDED.class_id,
  subclass_id = EXCLUDED.subclass_id,
  name = EXCLUDED.name,
  economy = EXCLUDED.economy,
  unlock_level = EXCLUDED.unlock_level,
  resource_slug = EXCLUDED.resource_slug,
  free_resource_slug = EXCLUDED.free_resource_slug,
  always_spends_resource = EXCLUDED.always_spends_resource,
  summary = EXCLUDED.summary,
  description = EXCLUDED.description,
  table_action = EXCLUDED.table_action,
  spend_amount = EXCLUDED.spend_amount,
  sort_order = EXCLUDED.sort_order;
